#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Priority {
    Standard,
    Express,
    SameDay,
}

fn main() {
    let mut queue = vec![Priority::Express, Priority::SameDay, Priority::Standard, Priority::Express];
    queue.sort();
    queue.dedup();
    println!("{:?} {}", queue, Priority::SameDay > Priority::Express);
}

